<template><NuxtLayout><h1>Device Inventory</h1><div class="panel"><h2>Add device</h2><div class="fields"><label>Name<input v-model="form.name" placeholder="SW-CORE-01"></label><label>Type<select v-model="form.device_type"><option v-for="t in types" :key="t" :value="t">{{t}}</option></select></label><label>Manufacturer<input v-model="form.manufacturer"></label><label>Model<input v-model="form.model"></label><label>Serial<input v-model="form.serial"></label><label>IP address<input v-model="form.ip_address"></label><label>VLAN / Management VLAN<input v-model="form.vlan"></label><label>Rack<select v-model="rackChoice"><option value="">Unplaced</option><option v-for="r in racks" :key="r.id" :value="String(r.id)">{{r.site_name}} — {{r.name}}</option></select></label><label>Start U<input v-model="position" type="number" min="1" max="60" placeholder="Optional"></label><label>Rack height (U)<input v-model.number="form.rack_height" type="number" min="1" max="60"></label><label>Number of ports<input v-model.number="form.port_count" type="number" min="0" max="192"></label><label>Notes<input v-model="form.notes"></label></div><p v-if="error" class="error">{{error}}</p><button :disabled="!editable" @click="add">Create device</button></div><section class="panel"><h2>All devices ({{devices.length}})</h2><input v-model="search" placeholder="Search devices, serials, IPs…" style="width:100%;margin-bottom:12px"><div class="table-wrap"><table><thead><tr><th>Name</th><th>Type</th><th>Model</th><th>IP</th><th>Site / Rack</th><th>U</th><th>Ports</th></tr></thead><tbody><tr v-for="d in filtered" :key="d.id"><td><strong>{{d.name}}</strong><div class="muted">{{d.serial}}</div></td><td>{{d.device_type}}</td><td>{{d.manufacturer}} {{d.model}}</td><td>{{d.ip_address}}</td><td>{{d.site_name||'—'}} / {{d.rack_name||'Unplaced'}}</td><td>{{d.rack_u||'—'}}</td><td>{{d.port_count}}</td></tr></tbody></table></div></section></NuxtLayout></template><script setup lang="ts">const auth=useAuth(),editable=computed(()=>['admin','editor'].includes(auth.value?.role));const {data:racks}=await useFetch<any[]>('/api/racks',{default:()=>[]});const {data:devices,refresh}=await useFetch<any[]>('/api/devices',{default:()=>[]});const types=['switch','patch_panel','server','router','firewall','ups','other'];const form=reactive({name:'',device_type:'switch',manufacturer:'',model:'',serial:'',ip_address:'',vlan:'',notes:'',rack_height:1,port_count:24});const rackChoice=ref(''),position=ref(''),search=ref(''),error=ref('');const filtered=computed(()=>devices.value.filter(d=>JSON.stringify(d).toLowerCase().includes(search.value.toLowerCase())));async function add(){error.value='';try{await $fetch('/api/devices',{method:'POST',body:{...form,rack_id:rackChoice.value?Number(rackChoice.value):null,rack_u:position.value?Number(position.value):null}});form.name='';form.serial='';form.ip_address='';await refresh()}catch(e:any){error.value=e?.data?.statusMessage||'Could not add device'}}</script>
